<?php
// Book migration, real rendering, complete games and unchanged frozen challenges.
$root=getenv('WP_ROOT');if(!$root||!is_file($root.'/wp-load.php')){exit("Set isolated WP_ROOT.\n");}$_SERVER['HTTP_HOST']='snd.test';$_SERVER['REQUEST_METHOD']='GET';$_SERVER['REQUEST_URI']='/';require $root.'/wp-load.php';
if(PHP_SAPI!=='cli'||!in_array(wp_get_environment_type(),array('local','development'),true)){exit('Refusing production.');}
$mb_n=0;$mb_tokens=array();$mb_settings=get_option('snd_settings',null);$mb_custom=get_option('snd_explore_catalogue',null);$mb_user=get_current_user_id();$mb_get=$_GET;
function mb_ok($v,$label){global $mb_n;$mb_n++;if(!$v){throw new RuntimeException($label);}}
function mb_api($route,$data){$r=new WP_REST_Request('POST','/srbija-na-dlanu/v1/'.$route);$r->set_header('Content-Type','application/json');$r->set_body(wp_json_encode($data));return rest_do_request($r);}
function mb_move($g,$action,$value=null){$r=mb_api('action',array('token'=>$g['token'],'revision'=>$g['state']['revision'],'action'=>$action,'value'=>$value));mb_ok($r->get_status()===200,'Real move '.$action);return $r->get_data();}
try{
 wp_set_current_user(0);delete_option('snd_explore_catalogue');SND_Explore::reset();update_option('snd_settings',SND_Settings::defaults(),false);SND_Settings::reset();SND_I18n::force('sr');SND_Site::install();
 $book=json_decode(file_get_contents(SND_DIR.'data/mountains-book.json'),true);$legacy_data=json_decode(file_get_contents(SND_DIR.'data/explore.json'),true);$legacy=array_column(array_filter($legacy_data['items'],function($t){return $t['kind']==='mountain';}),null,'id');$pool=SND_Explore::pool('mountain');
 mb_ok(count($book)===197&&count($pool)===197&&count(SND_Explore::targets('mountain'))===197,'All book positions are public and playable');mb_ok(array_sum(array_map(function($t){return count($t['book_pages']);},$book))===201,'All 201 source rows retain page references after four merges');
 mb_ok(count(array_unique(array_column($book,'id')))===197&&count(array_unique(array_map(function($t){return wp_json_encode($t['center']);},$book)))===197,'No repeated identity or reference point');
 foreach($legacy as $id=>$old){mb_ok(isset($pool[$id])&&in_array($old['name'],array_merge(array($pool[$id]['name']),$pool[$id]['aliases']),true),'Old names and IDs remain valid '.$id);}
 $photos=0;$directions=0;
 foreach($pool as $id=>$t){
  $point=SND_Explore::project($t['center']);mb_ok(abs($point[0]-$t['point'][0])<=.011&&abs($point[1]-$t['point'][1])<=.011,'Map pin agrees with published coordinates '.$id);
  $q=SND_Explore::questions($t,$pool,'book:'.$id);if($q[3]['type']==='explore_photo'){$photos++;}else{$directions++;mb_ok(strpos($q[3]['title_key'],'planina')!==false,'Missing image uses a mountain direction question '.$id);}
  mb_ok(count($q)===4&&!empty($t['book_pages'])&&$t['source']===SND_Explore::MOUNTAINS_SOURCE,'Four sourced questions and source pages '.$id);
  set_error_handler(function($severity,$message,$file,$line){throw new ErrorException($message,0,$severity,$file,$line);});ob_start();try{SND_Explore_Admin::detail($t);$html=ob_get_contents();}finally{ob_end_clean();restore_error_handler();}
  mb_ok(strpos($html,'Stranice izvora')!==false&&strpos($html,'<dt>Referentni vrh</dt>')!==false&&strpos($html,'<dt>Okrug</dt>')===false,'Detail renders source pages and a peak without a false administrative label '.$id);
 }
 mb_ok($photos===52&&$directions===145,'Exactly 52 licensed-photo and 145 direction tasks');
 $_GET=array('tip'=>'mountain');set_error_handler(function($severity,$message,$file,$line){throw new ErrorException($message,0,$severity,$file,$line);});ob_start();try{SND_Catalogue::library();$html=ob_get_contents();}finally{ob_end_clean();restore_error_handler();}mb_ok(substr_count($html,'data-catalogue-item=')===197,'All new records render in the knowledge table without warnings');
 foreach(array('en','de','ru') as $lang){SND_I18n::force($lang);foreach(array('Stranice izvora','Izvor za ovu planinu','Referentni vrh i koordinate','Jugozapadna Srbija','Kopaonička grupa') as $text){mb_ok(SND_I18n::t($text)!==$text,'New explanatory text translated '.$lang.' '.$text);}}SND_I18n::force('sr');
 // An old daily snapshot retains its original coordinates, facts, choices and attempts.
 $g=SND_Game::create('mountain','practice');mb_ok(!is_wp_error($g),'Create isolated legacy holder');$mb_tokens[]=$g['token'];$s=SND_Game::load($g['token']);$old=$legacy['mountain-1-2'];$c=$s['challenge'];$c['target']=$old;$c['catalog']=$legacy;$c['mode']='daily';$c['storage_key']='snd_mountains_book_frozen_test';$c['questions']=SND_Explore::questions($old,$legacy,'pre-book');$c['questions'][0]['title_key']='Koji je referentni vrh planine u pregledu PSS za Srbiju?';$c['questions'][0]['title']=$c['questions'][0]['title_key'];update_option($c['storage_key'],$c,false);$s['challenge']=$c;$wrong=array_keys(array_diff_key($legacy,array($old['id']=>true)))[0];mb_ok(SND_Game::act($s,'guess',$wrong)===true,'Existing wrong attempt');SND_Game::persist($g['token'],$s);$loaded=SND_Game::load($g['token']);
 mb_ok($loaded['challenge']===$c&&$loaded['guesses']===$s['guesses']&&count(SND_Game::public_state($loaded)['catalog'])===188,'Frozen mountain task and progress are untouched');mb_ok(get_option($c['storage_key'])===$c,'Stored daily task was not replaced');mb_ok(SND_Game::act($loaded,'guess',$old['id'])===true&&$loaded['solved'],'Old approved target is still answerable');SND_Game::act($loaded,'next',null);
 foreach($c['questions'] as $i=>$q){mb_ok(SND_Game::question_for($loaded,$i)===$q,'Saved answer identifiers retained '.$i);SND_Game::act($loaded,'answer',$q['correct']);SND_Game::act($loaded,'next',null);}mb_ok(SND_Scoring::calculate($loaded)['total']===94,'Old task finishes with its original 94-point score');
 // Complete both new question variants through the REST state machine.
 foreach(array('mountain-1-1'=>'explore_photo','mountain-book-017'=>'explore_direction') as $id=>$type){$g=SND_Game::create('mountain','practice');$mb_tokens[]=$g['token'];$s=SND_Game::load($g['token']);$s['challenge']['target']=$pool[$id];$s['challenge']['questions']=SND_Explore::questions($pool[$id],$pool,'new-book:'.$id);SND_Game::persist($g['token'],$s);$r=mb_api('resume',array('token'=>$g['token']));$g=$r->get_data();mb_ok(count($g['state']['catalog'])===197,'Fresh game uses full book catalogue');$g=mb_move($g,'guess',$id);$g=mb_move($g,'next');foreach($s['challenge']['questions'] as $q){$g=mb_move($g,'answer',$q['correct']);$g=mb_move($g,'next');}mb_ok($g['state']['stage']==='complete'&&$g['state']['points']['total']===100&&$s['challenge']['questions'][3]['type']===$type,'Complete new photo or direction game for 100 points');}
 echo 'PASS: '.$mb_n.' book-source records, warning-free details, map coordinates, legacy-day preservation and real 100-point mountain games.'.PHP_EOL;
}finally{foreach($mb_tokens as $token){delete_transient('snd_session_'.$token);}delete_option('snd_mountains_book_frozen_test');if($mb_settings===null){delete_option('snd_settings');}else{update_option('snd_settings',$mb_settings,false);}if($mb_custom===null){delete_option('snd_explore_catalogue');}else{update_option('snd_explore_catalogue',$mb_custom,false);}SND_Settings::reset();SND_Explore::reset();SND_I18n::force(null);wp_set_current_user($mb_user);$_GET=$mb_get;}
